package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create whose lastName and address already belong to another owner (compared
 * case-insensitively with collapsed whitespace), before {@link SaveOwner} runs. Handled
 * with 409 by {@code DuplicateHouseholdHandler}. Skipped when the request opts in with
 * {@code sharesHousehold=true}.
 */
public class CheckUniqueHousehold {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String address = normalize(owner.getAddress());
        for (Owner other : ownerRepository.findAll()) {
            if (!other.getId().equals(owner.getId())
                    && lastName.equals(normalize(other.getLastName()))
                    && address.equals(normalize(other.getAddress()))) {
                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
            }
        }
    }

    /** Lower-cases and collapses runs of whitespace to a single space so that
     *  case and spacing differences do not defeat the household match. */
    static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects a create whose whole {@code identityKey} already belongs to another owner,
 * before {@link SaveOwner} runs. Consolidates the former telephone, email and household
 * duplicate checks: only an exact full-key match is a duplicate, so two members of the
 * same household with different telephones are both allowed. Handled with 409 by
 * {@code DuplicateIdentityHandler}. Runs after {@link AssignHouseholdId} so the key can
 * include the household part.
 */
public class CheckUniqueIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String key = identityKey(owner);
        for (Owner other : ownerRepository.findAll()) {
            if (!other.getId().equals(owner.getId()) && key.equals(identityKey(other))) {
                throw new DuplicateIdentityException(key);
            }
        }
    }

    /** Derived duplicate key: normalizedTelephone + '|' + (email or empty) + '|' + householdId. */
    public static String identityKey(Owner owner) {
        return blank(owner.getTelephone()) + "|" + blank(owner.getEmail()) + "|"
                + blank(owner.getHouseholdId());
    }

    private static String blank(String value) {
        return value == null ? "" : value;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

public class BuildOwner {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
            Out<Boolean> sharesHousehold) throws MissingOwnerFieldsException {
        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
        Map<String, String> required = new LinkedHashMap<>();
        required.put("firstName", request.getFirstName());
        required.put("lastName", request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        required.put("address", address);
        required.put("city", request.getCity());
        required.put("telephone", request.getTelephone());
        List<String> missing = required.entrySet().stream()
                .filter(e -> e.getValue() == null || e.getValue().isBlank())
                .map(Map.Entry::getKey).toList();
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        Owner owner = ownerMapper.toOwner(request);
        String telephone = toE164(owner.getTelephone());
        if (telephone == null) {
            throw new MissingOwnerFieldsException(List.of("telephone"));
        }
        owner.setTelephone(telephone);
        owner.setAddress(address);
        String email = owner.getEmail();
        if (email != null && !EMAIL.matcher(email).matches()) {
            throw new MissingOwnerFieldsException(List.of("email"));
        }
        built.set(owner);
    }

    /**
     * Normalizes a raw telephone to E.164. A leading '+' keeps its country code;
     * otherwise '+61' is assumed and a single leading '0' is dropped. Spaces, dashes
     * and brackets are stripped. Returns null when the national-number length is
     * wrong for the country code (see {@link E164Length}).
     */
    static String toE164(String raw) {
        String trimmed = raw.trim();
        String digits;
        if (trimmed.startsWith("+")) {
            digits = trimmed.substring(1).replaceAll("\\D", "");
        }
        else {
            String national = trimmed.replaceAll("\\D", "");
            digits = "61" + (national.startsWith("0") ? national.substring(1) : national);
        }
        return E164Length.isValid(digits) ? "+" + digits : null;
    }
}
